// План specs/schedule-day.md 1.1–1.2 (кейсы .qa/tests/schedule-day/SD-01, SD-02). Admin, компания «test», десктоп. Только просмотр.
// Данные: в «test» на Wed, Oct 14, 2026 — JOB-0052 (03:55, «QA-date 2 …») и JOB-0076 (23:30, «QA-datev 2330»).
// Время браузера — как при ручной проверке (часовой пояс раннера не меняется): время работы хранится как время суток.
// Не сверено с сайтом при записи: подписи часов сетки — отдельные элементы с текстом «HH:00» (24 ч); переключатель Day — tab или button.
import { test, expect, Page } from '@playwright/test';
import { ADMIN_STATE, Lang, blockSmsSending, expectNoSmsSent, restoreCompany, useLang } from '../job-dates/job-dates-helpers';

test.use({ storageState: ADMIN_STATE });

const TARGET = { y: 2026, m: 10, d: 14 };
const HEADING = { en: 'Wednesday, October 14, 2026' };

const hourLabels = (page: Page) => page.locator('main').getByText(/^\s*\d{2}:00\s*$/);

async function openScheduleDay(page: Page, lang: Lang) {
  await page.goto('/dashboard');
  await page.getByRole('link', { name: lang === 'en' ? 'Schedule' : 'לוח זמנים', exact: true }).first().click();
  await expect(page.locator('main')).toContainText(/\d{2}:00|Day|יום/, { timeout: 30_000 });
  const day = lang === 'en' ? 'Day' : 'יום';
  await page.getByRole('tab', { name: day, exact: true }).or(page.getByRole('button', { name: day, exact: true })).first().click();
}

/** Шагами Previous/Next от сегодняшнего дня к Oct 14, 2026 (EN), ждём заголовок дня. */
async function goToTargetDay(page: Page) {
  const now = new Date();
  const diff = Math.round((Date.UTC(TARGET.y, TARGET.m - 1, TARGET.d) - Date.UTC(now.getFullYear(), now.getMonth(), now.getDate())) / 86_400_000);
  const btn = page.getByRole('button', { name: diff < 0 ? /Previous/ : /Next/ });
  for (let i = 0; i < Math.abs(diff); i++) await btn.first().click();
  await expect(page.getByText(HEADING.en, { exact: true }).first()).toBeVisible({ timeout: 30_000 });
}

/** Подписи часов сетки по порядку. */
async function hours(page: Page): Promise<string[]> {
  await expect(hourLabels(page).first()).toBeVisible({ timeout: 30_000 });
  return (await hourLabels(page).allInnerTexts()).map((s) => s.trim());
}

/** Минуты от полуночи для «3:55 AM» / «11:30 PM». */
const toMinutes = (h: string, m: string, ap: string) => ((Number(h) % 12) + (ap === 'PM' ? 12 : 0)) * 60 + Number(m);

test.describe('Schedule Day: grid expands for early and late jobs (#6c02bf)', () => {
  test('Schedule Day (EN), Oct 14 2026: grid runs 03:00–23:00 and shows the 3:55 AM and 11:30 PM jobs in place #6c02bf @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(240_000);
    await useLang(page, 'en');
    const smsHits = await blockSmsSending(page);
    try {
      await openScheduleDay(page, 'en');
      await goToTargetDay(page);
      // Источник: «מה רצוי» — כל העבודות של היום מוצגות; комментарий программиста — 03:00…23:00 для 03:55 и 23:30.
      const h = await hours(page);
      expect(h[0], 'первая строка сетки').toBe('03:00');
      expect(h[h.length - 1], 'последняя строка сетки').toBe('23:00');
      const main = page.locator('main');
      await expect(main.getByText('3:55 AM', { exact: true }).first()).toBeVisible();
      await expect(main.getByText('11:30 PM', { exact: true }).first()).toBeVisible();
      // Работа 03:55 стоит в строке 03:00 — ниже подписи 03:00 и выше 04:00.
      const y = async (t: string) => (await main.getByText(t, { exact: true }).first().boundingBox())!.y;
      const y0355 = await y('3:55 AM');
      expect(y0355).toBeGreaterThan(await y('03:00'));
      expect(y0355).toBeLessThan(await y('04:00'));
      expect(await y('11:30 PM')).toBeGreaterThan(await y('23:00'));
      // Строка отладки убрана (комментарий программиста).
      await expect(page.getByText(/Debug: Total items received/)).toHaveCount(0);
    } finally {
      await restoreCompany(page);
    }
    expectNoSmsSent(smsHits);
  });

  test('Schedule Day (HE), Oct 14 2026: grid includes 03:00 and 23:00 and the 23:30 job is shown #6c02bf @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(240_000);
    await useLang(page, 'en');
    const smsHits = await blockSmsSending(page);
    try {
      // Переход к дню — в EN (заголовок дня проверяется по-английски), затем смена языка и перезагрузка.
      await openScheduleDay(page, 'en');
      await goToTargetDay(page);
      await useLang(page, 'he');
      await page.reload();
      // // не проверено: сохраняется ли выбранный день после перезагрузки. Если нет — снова к дню через кнопки.
      if (!(await page.locator('main').getByText('23:30', { exact: true }).first().isVisible().catch(() => false))) {
        await openScheduleDay(page, 'he');
        const now = new Date();
        const diff = Math.round((Date.UTC(TARGET.y, TARGET.m - 1, TARGET.d) - Date.UTC(now.getFullYear(), now.getMonth(), now.getDate())) / 86_400_000);
        const btn = page.getByRole('button', { name: diff < 0 ? /הקודם|קודם/ : /הבא/ });
        for (let i = 0; i < Math.abs(diff); i++) await btn.first().click();
      }
      const main = page.locator('main');
      await expect(main.getByText('23:30', { exact: true }).first()).toBeVisible({ timeout: 30_000 });
      await expect(main.getByText('03:00', { exact: true }).first()).toBeVisible();
      await expect(main.getByText('23:00', { exact: true }).first()).toBeVisible();
    } finally {
      await useLang(page, 'en');
      await restoreCompany(page);
    }
    expectNoSmsSent(smsHits);
  });

  test('Schedule Day (EN), today: grid is 06:00–22:00 unless a job starts earlier/later, then it starts/ends at that hour #6c02bf @desktop @prod-safe', async ({ page }) => {
    await useLang(page, 'en');
    const smsHits = await blockSmsSending(page);
    try {
      await openScheduleDay(page, 'en');
      await page.getByRole('button', { name: 'Today', exact: true }).click();
      const h = await hours(page);
      // Время работ дня (EN «h:mm AM/PM»; подписи сетки — «HH:00», в выборку не попадают).
      const times = ((await page.locator('main').innerText()).match(/\b(\d{1,2}):(\d{2}) (AM|PM)\b/g) ?? [])
        .map((t) => { const [, hh, mm, ap] = t.match(/(\d{1,2}):(\d{2}) (AM|PM)/)!; return toMinutes(hh, mm, ap); });
      const minHour = Math.min(6, ...times.map((m) => Math.floor(m / 60)));
      const maxHour = Math.max(22, ...times.map((m) => Math.floor(m / 60)));
      const pad = (n: number) => `${String(n).padStart(2, '0')}:00`;
      // Источник: комментарий программиста — по умолчанию 06:00–22:00, расширяется до часа ранней/поздней работы.
      expect(h[0], `первая строка (время работ: ${times.length})`).toBe(pad(minHour));
      expect(h[h.length - 1], 'последняя строка').toBe(pad(maxHour));
    } finally {
      await restoreCompany(page);
    }
    expectNoSmsSent(smsHits);
  });
});
